  `openmeteo_precipitation` double DEFAULT NULL,
  `openmeteo_wind_speed` double DEFAULT NULL,
  `nasa_temperature` double DEFAULT NULL,
  `nasa_precipitation` double DEFAULT NULL,
  `nasa_wind_speed` double DEFAULT NULL,
  `nasa_solar_radiation` double DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
